import { describe, expect, it } from "vitest";
import { readFileSync } from "node:fs";
import { deriveMailboxKey, open, pad, sealJson, type Role } from "../tools/mailbox-cipher.ts";

// The vectors are generated by tools/gen-mailbox-vectors.ts; the cipher is the reference in tools/mailbox-cipher.ts.
const vectors = JSON.parse(readFileSync(new URL("../test-vectors-mailbox.json", import.meta.url), "utf8"));
const shared = JSON.parse(readFileSync(new URL("../test-vectors.json", import.meta.url), "utf8"));
const bytes = (s: string) => Buffer.from(s, "hex");

describe("coucou-mailbox/v1 vectors", () => {
  it("uses the same synthetic key and room as the live-channel vectors", () => {
    expect(vectors.inputs.key).toBe(shared.inputs.key);
    expect(vectors.inputs.room).toBe(shared.inputs.room);
  });

  it("derives K_mailbox from K with HKDF info 'coucou-relay/v1 mailbox'", () => {
    const kMailbox = deriveMailboxKey(bytes(vectors.inputs.key));
    expect(kMailbox.toString("hex")).toBe(vectors.kMailbox);
  });

  const kMailbox = bytes(vectors.kMailbox);

  vectors.messages.forEach((m: { to: string; nonce: string; body: string; json: string; plaintextPadded: string }, i: number) => {
    it(`message ${i} (to ${m.to}) opens to its json and re-seals to the same body`, () => {
      const to = m.to as Role;
      expect(open(kMailbox, vectors.inputs.room, to, bytes(m.body))).toEqual({ ok: true, json: m.json });
      expect(pad(m.json).toString("hex")).toBe(m.plaintextPadded);
      expect(sealJson(kMailbox, vectors.inputs.room, to, bytes(m.nonce), m.json).toString("hex")).toBe(m.body);
    });
  });

  vectors.mustRefuse.forEach((n: { name: string; room: string; to: string; body: string; expect: string }) => {
    it(`refuses: ${n.name}`, () => {
      expect(open(kMailbox, n.room, n.to as Role, bytes(n.body))).toEqual({ ok: false, reason: n.expect });
    });
  });
});
